
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_pbe_erf_gws_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_pbe_erf_gws", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.272253696577765e-02, -6.167710862420437e-02, -6.017907837803883e-02, -5.803627238430398e-02, -5.497973069062355e-02, -5.064137878050201e-02, -4.454663451285357e-02, -3.619876592180667e-02, -2.556410178265629e-02, -1.476885456929846e-02, -1.097176325676887e-02, -3.378626870764470e-02, -3.763365638148884e-02, -2.727021679211603e-02, -1.561802658962447e-02, -6.603907726674202e-03, -1.168146860005600e-03, -2.422443492336290e-05, -7.093926022891559e-08, -2.068359880669819e-11]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


